// Reads Jev's answer and picks a lane. Thresholds live in code (tunable), not in the prompt.
const out = [];
for (const item of $input.all()) {
  const a = item.json.answers || {};
  const probs = Object.values(a.intent?.probabilities || {});
  const n = probs.length || 1;
  const pmax = probs.length ? Math.max(...probs) : 0;
  const confidence = n > 1 ? Math.max(0, (pmax - 1 / n) / (1 - 1 / n)) : 0; // official Choice formula
  const vendor = a.vendor?.probability ?? a.vendor?.noul;
  let lane = confidence >= 0.85 ? 'auto' : confidence >= 0.6 ? 'review' : 'human';
  if (!a.intent?.choice || typeof vendor !== 'number') lane = 'human';   // missing answer: never automate
  else if (a.intent.choice === 'existing_client') lane = 'human';
  else if (vendor >= 0.8) lane = 'archive';
  out.push({ json: { intent: a.intent?.choice, confidence: Number(confidence.toFixed(2)), vendor, lane,
    cost_usd: item.json.providerMetadata?.gateway?.cost } });
}
return out;
